package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamKandyTradBank2 {
    private const val T = "මහනුවර යුගයේ සිතුවම්, දේශීය ශෛලිය හා වාස්තු කැටයම්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("මහනුවර යුගයේ දැව කැටයම් කලාවේ අග්‍රගණ්‍ය නිර්මාණය ලෙස සැලකෙන ඇම්බැක්කේ දේවාලය පිහිටියේ කුමන දිස්ත්‍රික්කයේද?", "මහනුවර දිස්ත්‍රික්කයේ උඩුනුවර", "අනුරාධපුර දිස්ත්‍රික්කයේ", "මාතර දිස්ත්‍රික්කයේ", "ගාල්ල දිස්ත්‍රික්කයේ", "මහනුවර දිස්ත්‍රික්කයේ උඩුනුවර ඇම්බැක්කේ දේවාලයේ දැව කණු හා පේකඩ විශිෂ්ට කලා කෘති වේ."),
        q("ඇම්බැක්කේ දේවාලයේ දැව කැටයම්වල ප්‍රධාන වශයෙන් නිරූපිත සාම්ප්‍රදායික කාන්තා මෝස්තරය කුමක්ද?", "පංචනාරි ඝටය", "ලියවැල පමණි", "සඳකඩපහණ", "ත්‍රිශූලය", "කාන්තාවන් පස්දෙනෙකු එක්ව පූර්ණ කළයක් මෙන් නිර්මාණය කළ පංචනාරි ඝටය ඇම්බැක්කේ සුප්‍රකට කැටයමකි."),
        q("ඇම්බැක්කේ දේවාලයේ හේවිසි මණ්ඩපයේ දැව කුළුණු කීයක් පමණ කැටයමින් අලංකාර කර තිබේද?", "කුළුණු 32 ක් පමණ", "කුළුණු 2 ක් පමණි", "කුළුණු 500 ක්", "කුළුණු 4 ක් පමණි", "හේවිසි මණ්ඩපයේ දැව කණු 32ක පමණ විවිධ සත්ව, නැටුම් හා මල් මෝස්තර කැටයම් කර ඇත."),
        q("ඇම්බැක්කේ දේවාලයේ වහලය දරා සිටින දැව බාල්ක පේළි හිස මත හමුවන ඉතා විශිෂ්ට වාස්තු අංගය කුමක්ද?", "මඩොල් කුරුපාව", "සඳකඩපහණ", "වාහල්කඩ", "වටදාගෙය", "පරාල විසි හයක් පමණ එකට හමුවී පිහිටුවන මඩොල් කුරුපාව ලී වඩු කර්මාන්තයේ විස්මයකි."),
        q("ඇම්බැක්කේ දේවාලයේ කැටයම් නිර්මාණය කළ ප්‍රධාන ශිල්පියා ලෙස ජනප්‍රවාදයේ සඳහන් වන්නේ කවුද?", "දෙවනගල දෙල්මඩ මූලාචාරියා", "දේවරගම්පල සිල්වත් තැන", "නීලගම පටබැඳි", "ජෝර්ජ් කීට්", "ගම්පොළ හතරවන වික්‍රමබාහු රජ සමයේ දෙල්මඩ මූලාචාරී ඇම්බැක්කේ කැටයම් කළ බව සැලකේ."),
        q("සිංහල සාම්ප්‍රදායික සැරසිලි කලාවේ 'වක්‍රාකාරව නැවී යන වැල් රටාව' හඳුන්වන්නේ කුමන නමකින්ද?", "ලියවැල", "පලාපෙති", "කතිර මල", "මකර තොරණ", "ශාකමය කොළ හා පොහොට්ටු සහිතව දඟර ගැසී අඛණ්ඩව යන සැරසිලි රටාව ලියවැලයි."),
        q("ලියවැල් දෙකක් එකිනෙක වෙළී ඇඹරී යන ආකාරයට නිර්මාණය කරන මෝස්තරය හඳුන්වන්නේ කෙසේද?", "ලියපත හෙවත් ද්විත්ව ලියවැල", "බිනරමල", "අරිම්බුව", "පනාව", "වැල් දෙකක් එකිනෙක පටලවා සකසන රටාව සාම්ප්‍රදායික කලාකරුවෝ ද්විත්ව ලියවැල හෝ දඟර ලියවැල ලෙස හඳුන්වති."),
        q("බොහෝ මහනුවර යුගයේ කැටයම් හා සිතුවම්වල දාර (Borders) සැරසීමට යොදා ගන්නා 'පෙති පේළිය' කුමක්ද?", "පලාපෙති මෝස්තරය", "භේරුණ්ඩ පක්ෂියා", "ගජසිංහ රූපය", "වෘෂභ කුංජරය", "නෙළුම් මල් පෙති ආකාරයෙන් පේළියට අඳින හෝ කපන දාර මෝස්තරය පලාපෙති නම් වේ."),
        q("හංසයන් දෙදෙනෙකුගේ ගෙල එකිනෙක පැටලී සමමිතිකව සකසා ඇති සාම්ප්‍රදායික දේශීය මෝස්තරය කුමක්ද?", "හංස පූට්ටුව", "කිඳුරු රූපය", "මකර රූපය", "නාරිලතා මල", "හංසයන් දෙදෙනෙකු හෝ කිහිප දෙනෙකු ගෙල පටලවාගෙන සිටින සැරසිලි රටාව හංස පූට්ටුවයි."),
        q("හිස් දෙකක් හා එක් සිරුරක් සහිතව උඩරට කොඩි හා කැටයම්වල දක්නට ලැබෙන මනඃකල්පිත පක්ෂි රූපය කුමක්ද?", "භේරුණ්ඩ පක්ෂියා", "ගුරුළු පක්ෂියා", "සැළලිහිණියා", "මොණර පක්ෂියා", "බලය හා තේජස සංකේතවත් කරන ද්විශීර්ෂ භේරුණ්ඩ පක්ෂියා සතර කෝරළ කොඩියේද ප්‍රධාන ලාංඡනයයි."),
        q("ඇතෙකුගේ හිස හා හොඬවැලත් සිංහයෙකුගේ ශරීරයත් එක් කොට නිමවන ලද උඩරට සාම්ප්‍රදායික සත්ව මෝස්තරය කුමක්ද?", "ගජසිංහ රූපය", "නරසිංහ රූපය", "සැරපෙන්දියා", "මකර රූපය", "ඇතාගේ ශක්තිය හා සිංහයාගේ තේජස එක් කළ මනඃකල්පිත රූපය ගජසිංහ නම් වේ."),
        q("සත්ව හා පක්ෂි සිරුරුවලින් අලංකාර කොට පිළිමගෙවල් හා උළුවහු මත ඉදි කරන අර්ධ වෘත්තාකාර තොරණ කුමක්ද?", "මකර තොරණ", "වාහල්කඩ", "සඳකඩපහණ", "සෝපානය", "කීර්තිමුඛ හා මකර රූප දෙපසින් යුත් මකර තොරණ විහාර දොරටු හා බුදු පිළිම පසුබිමේ බහුලව යෙදේ."),
        q("මකර තොරණේ මුදුනේම සිටින රෞද්‍ර මුහුණක් සහිත සාම්ප්‍රදායික ආරක්ෂක මෝස්තරය කුමක්ද?", "කිඹිහි මුහුණ (කීර්තිමුඛ)", "පංචනාරි ඝටය", "හංස පූට්ටුව", "අරිම්බුව", "දුෂ්ට බලවේග පලවා හැරීමේ සංකේතයක් ලෙස මකර තොරණේ මුදුනේ කිඹිහි මුහුණ අඹනු ලැබේ."),
        q("ගොනු සහ ඇතු යන සතුන් දෙදෙනාගේ හිස් එකම ශරීර අංග පොදුවේ භාවිත වන සේ අඳින ප්‍රහේලිකා මෝස්තරය කුමක්ද?", "වෘෂභ කුංජරය", "ගජසිංහයා", "සැරපෙන්දියා", "භේරුණ්ඩ පක්ෂියා", "වම් පසින් ගවයෙකුද දකුණු පසින් ඇතෙකුද ලෙස පෙනෙන මෙය විස්මිත දේශීය සංකලන මෝස්තරයකි."),
        q("හිමගිරි වැනි කඳුකර පරිසරයක පිපෙන බවට ජනප්‍රවාදයේ එන, ස්ත්‍රී රූපයක් වැනි මනඃකල්පිත මල් මෝස්තරය කුමක්ද?", "නාරිලතා මල", "කඩුපුල් මල", "නෙළුම් මල", "සීන මල", "තාපසවරුන්ගේ ධ්‍යාන බිඳින බවට පැරණි කතාවල එන නාරිලතා මල ඇම්බැක්කේ හා මහනුවර කැටයම්වල ප්‍රකටය."),
        q("මහනුවර යුගයේ කැටයම්වල හමුවන මල් හා පත්‍ර ඇඳීමේදී පොදුවේ පිළිගත් සාම්ප්‍රදායික පුහුණු මෝස්තරය කුමක්ද?", "වංකගිරිය හා කතුරු මල", "පුනරුද ත්‍රිමාණ කැටයම", "ග්‍රීක අයනික කුළුණු හිස", "බැරොක් කැටයම", "ආධුනික සිත්තරා මුලින්ම වංකගිරිය, කතුරු මල, සීන මල හා නාරිලතා ඇඳීම ප්‍රගුණ කරයි."),
        q("සාම්ප්‍රදායික කලා ශිල්පියෙකු පුහුණු වීමේදී 'වක්‍ර රේඛා හා පිරිසිදු මෝස්තර' පුරුදු වීමට භාවිත කළ මූලික රටාව කුමක්ද?", "වංකගිරිය (වැල් පටලැවිල්ල)", "ත්‍රිමාණ ගණිත රූපය", "මානව ඇටසැකිල්ල", "නාගරික භූ දර්ශනය", "රේඛා පාලනය හා අත හුරු කරවීම සඳහා වංකගිරිය ඇඳීම සිංහල කලා අධ්‍යාපනයේ මුල් පියවර විය."),
        q("ගම්පොළ යුගයේ සිට මහනුවර යුගය දක්වා විකාශනය වූ 'ටැම්පිට විහාර' ගොඩනැගිලි නිර්මාණයේ ප්‍රධාන ලක්ෂණය කුමක්ද?", "කෙටි ගල් කණු මත ලී තට්ටුවක් දමා ඒ මත පිළිමගෙය ඉදි කිරීම", "මුහුද මැද කළුගල් දූපතක ගොඩනැගීම", "ගසක් මුදුනේ තාවකාලිකව තැනීම", "පොළොව යට උමඟක කැණීම", "වේයන්ගෙන් හා තෙතමනයෙන් ආරක්ෂා වීම සඳහා ගල් ටැම් මත දැව වේදිකාවක් සාදා විහාරය තැනීය."),
        q("පහත සඳහන් විහාර අතරින් මහනුවර සම්ප්‍රදායේ ප්‍රකට 'ටැම්පිට විහාරයකට' නිවැරදි උදාහරණය කුමක්ද?", "මැදවල රජමහා විහාරය", "සීගිරි ජල උද්‍යානය", "ථූපාරාම දාගැබ", "ජේතවනාරාම පිළිමගෙය", "මැදවල, බිංගිරිය හා දඹදෙණිය වැනි ස්ථානවල අලංකාර සිතුවම් සහිත ටැම්පිට විහාර හමුවේ."),
        q("ගම්පොළ යුගයේ ඉදි වී මහනුවර යුගයේ ප්‍රතිසංස්කරණයට ලක් වූ 'ලංකාතිලක විහාරය' පිහිටියේ කොහේද?", "හිඳගල හා උඩුනුවර ආසන්න හියාරපිටියේ", "පොළොන්නරුව ආලාහන පිරිවෙනේ", "යාපනය අර්ධද්වීපයේ", "හම්බන්තොට තිස්සමහාරාමයේ", "ගලගෙදර නොව උඩුනුවර හියාරපිටියේ ගල් තලාවක් මත ලංකාතිලක විහාරය ඉදි කර ඇත."),
        q("ගඩලාදෙණිය විහාරයේ වාස්තු විද්‍යාත්මක සැලැස්ම හා කැටයම් තුළ කැපී පෙනෙන විදේශීය ආභාසය කුමක්ද?", "දකුණු ඉන්දීය විජයනගර ආභාසය", "ඊජිප්තු පිරමීඩ ආභාසය", "ග්‍රීක පාතිනන් ආභාසය", "චීන පැගෝඩා ආභාසය", "ධර්මකීර්ති හිමිගේ අනුශාසනාවෙන් ගණේශ්වරාචාරී විසින් දකුණු ඉන්දීය ගල් කැටයම් ආරට ගඩලාදෙණිය තැනීය."),
        q("මහනුවර දළදා මාලිගාව අසල පිහිටි රජුගේ රාජ සභාව පැවති විවෘත දැව මණ්ඩපය කුමක්ද?", "මගුල් මඩුව (අවසන් මහනුවර රාජසභාව)", "ලෝවාමහාපාය", "නිශ්ශංක ලතා මණ්ඩපය", "පොත්ගුල් වෙහෙර", "ශ්‍රී වික්‍රම රාජසිංහ රජ සමයේ ඉදි කළ මගුල් මඩුවේ කැටයම් කළ දැව කුළුණු පේළි හමුවේ."),
        q("මහනුවර යුගයේ 'පේකඩ' යනුවෙන් හැඳින්වෙන්නේ ගොඩනැගිල්ලක කුමන කොටසද?", "බාල්ක දරන කැටයම් දැව කොටස", "වහලයේ මුදුන් උළු කැටය", "පිළිමගෙයි යතුරු තහඩුව", "බිම අතුරන කළුගල් පුවරුව", "කුළුණු හිස මත බාල්ක සම්බන්ධ කරන පේකඩවල එල්ලෙන නෙළුම් මල් පොහොට්ටු කැටයම් දක්නට ඇත."),
        q("පේකඩ කැටයම්වල පහළට එල්ලෙන ආකාරයට කැටයම් කර ඇති සාම්ප්‍රදායික මල් අංගය හඳුන්වන්නේ කෙසේද?", "බිංදු නෙළුම හෙවත් එල්ලෙන පොහොට්ටුව", "ලියවැල් දඟර මෝස්තරය", "ගජසිංහ හිස කැටයම", "අර්ධ සඳකඩපහණ", "ඇම්බැක්කේ හා මගුල් මඩුවේ පේකඩවල පහළට නෙරූ අලංකාර නෙළුම් පොහොට්ටු කැටයම් වේ."),
        q("සාම්ප්‍රදායික උඩරට කලාවේ රන්, රිදී හෝ දැව කලා භාණ්ඩ මත දාර අලංකරණයට යොදන කුඩා රවුම් තිත් පෙළ කුමක්ද?", "අරිම්බුව", "පනාව", "ලියවැල", "වැල්පොට", "සමාන ප්‍රමාණයේ කුඩා තිත් හෝ මුතු පෙළක් මෙන් යොදන අලංකාර දාර රටාව අරිම්බුවයි."),
        q("මහනුවර යුගයේ දොර උළුවහු හා ගෘහ අලංකරණයේදී බහුලව යොදාගත් 'ගිනි දැල් හෝ තුඩු ආකාර' දාර මෝස්තරය කුමක්ද?", "දැති හෙවත් ගිනිසිළු මෝස්තරය", "වෘෂභ කුංජරය", "පංචනාරි ඝටය", "හංස පූට්ටුව", "රේඛීය ජ්‍යාමිතික රටා අතර තුඩු පේළි ලෙස යොදන දැති හා කුන්දිරක්කන් දාර මෝස්තර ප්‍රකටය."),
        q("දේශීය සාම්ප්‍රදායික මෝස්තර කලාවේ 'කුන්දිරක්කන්' යනුවෙන් හැඳින්වෙන්නේ කුමන රටාවද?", "සමචතුරස්‍ර දියමන්ති බෝඩරය", "දඟර ගැසුණු හංස පෙළ", "පිපුණු නෙළුම් මල", "මකරාගේ වලිගය", "ත්‍රිකෝණ හා රොම්බස් හැඩතල අනුක්‍රමයෙන් යෙදෙන ජ්‍යාමිතික බෝඩරය කුන්දිරක්කන් නම් වේ."),
        q("සාම්ප්‍රදායික කලා කර්මාන්තයක් වන 'ලාක්ෂා කලාව' (Lacquer Work) සඳහා ලංකාවේ වඩාත් ප්‍රසිද්ධ උඩරට ග්‍රාමය කුමක්ද?", "මාතලේ හපුවිද හා පල්ලේ හපුවිද", "අම්බලන්ගොඩ", "කැලණිය", "මන්නාරම", "මහනුවර යුගයේ සිට ලාක්ෂා කර්මාන්තය මාතලේ හපුවිද ප්‍රදේශයේ පාරම්පරිකව පවත්වාගෙන එයි."),
        q("ලාක්ෂා කලාවේදී ලී උපකරණ (සැරයටි, හෙප්පු, සේසත් මිටි) අලංකාර කිරීමට යොදා ගන්නා ප්‍රධාන ද්‍රව්‍යය කුමක්ද?", "ලක්කඩ (කෘමීන්ගෙන් ලැබෙන ස්වභාවික රෙසිනය)", "ප්ලාස්ටික් ටේප්", "ඇලුමිනියම් තහඩු", "ජල සායම් තීන්ත", "ලක්කඩ රත් කර වර්ණ ගන්වා කූරු ලෙස සාදා කැරකෙන ලී මත ඇතිල්ලීමෙන් ලාක්ෂා රටා යොදයි."),
        q("මාතලේ පාරම්පරික ලාක්ෂා කර්මාන්තයේ ප්‍රධාන වශයෙන් යොදා ගන්නා ශෛලීන් දෙක මොනවාද?", "නියපොතු වැඩ සහ පට්ටල් වැඩ", "තෙල් සායම් සහ ජල සායම්", "මොසැයික් සහ කොලාජ්", "ලිනෝ කට් සහ ස්ටෙන්සිල්", "පට්ටලයේ කරකවා වර්ණ තැවරීම හා ඇඟිල්ලෙන් තියුණු නියපොතු මෝස්තර ඇදීම සිදු කරයි."),
        q("මහනුවර යුගයේ 'ඇත්දත් කැටයම්' කලාව සඳහා ප්‍රකට නිර්මාණ හමුවන ස්ථාන මොනවාද?", "දළදා මාලිගාව හා ඇම්බැක්කේ", "සීගිරිය හා ඉසුරුමුණිය", "ගාල්ල ලන්දේසි කොටුව", "තිස්සමහාරාම දාගැබ", "මහනුවර යුගයේ විහාර උළුවහු, වටාපත් මිටි, පනා හා කුඩා කරඬු ඇත්දළින් සියුම්ව කැටයම් කළේය."),
        q("දළදා මාලිගාවේ හා රිදී විහාරයේ දක්නට ලැබෙන ඇත්දත් කැටයම් කළ දොර උළුවහුවල විශේෂ ලක්ෂණය කුමක්ද?", "පංචනාරි ඝටය හා හංස පූට්ටුව", "යකඩ ඇණ පමණක් ගසා තිබීම", "පැතලි සුදු තීන්ත ගා තිබීම", "ගඩොල් බදාමෙන් තැනීම", "ඇත්දත් තීරු මත සූක්ෂ්ම කැටයම් ශිල්පයෙන් විහාර දොරටු අලංකාර කර ඇත."),
        q("මහනුවර යුගයේ දී විශේෂයෙන් නිපදවූ කැටයම් සහිත දේශීය 'පිත්තල හා ලෝහ කර්මාන්ත' (නැවැන්දුම්/තැම්බුම්) නිර්මාණ සඳහා ප්‍රසිද්ධ ප්‍රදේශය කුමක්ද?", "පිළිමතලාව හා ගඩලාදෙණිය අවට ගම්මාන", "තංගල්ල", "මඩකලපුව", "අනුරාධපුර", "පිළිමතලාව හා නීලවල ආශ්‍රිත ශිල්පීන් පහන්, සේරක්කාලි, කෙන්ඩි හා කස්තාන නිපදවූහ."),
        q("මහනුවර යුගයේ පිත්තල හා තඹ භාණ්ඩවල සිදු කරන 'තහඩු මත කොටා ඇති රිදී හෝ පිත්තල රටා' ශිල්පය කුමක්ද?", "සිත්තරු කෙටුම් හා රිදී වැඩ (Damascening / Inlay)", "ඩිජිටල් ලේසර් කැපුම", "ප්ලාස්ටික් අච්චු ගැසීම", "තෙල් සායම් පින්තාරුව", "යකඩ හෝ පිත්තල තහඩුවක කට්ටා කපා රිදී හෝ තඹ කම්බි ඔබ්බවා සියුම් මෝස්තර තැනීමයි."),
        q("සිංහල සාම්ප්‍රදායික කලාවේ 'මහා වංශකතා හා ජාතක කතා' මෙන්ම 'සේසත්' නිර්මාණය කළ ප්‍රධාන සිත්තර ග්‍රාමය කුමක්ද?", "මාතලේ උනවේරුව", "හම්බන්තොට", "මීගමුව", "බදුල්ල", "මාතලේ උනවේරුව ග්‍රාමයේ ශිල්පීහු දළදා පෙරහැරේ සේසත් හා චාමර පාරම්පරිකව නිපදවති."),
        q("උඩරට සාම්ප්‍රදායික 'දුම්බර රටා' (දුම්බර පැදුරු හා කළාල) නිර්මාණය සඳහා භාවිත කරන ප්‍රධාන ස්වභාවික තන්තුව කුමක්ද?", "නියඳ කෙඳි (Hemp fibres)", "නයිලෝන් නූල්", "කපු රෙදි පටි පමණක්", "කෙසෙල් කඳන් පටි", "මාතලේ හා මහනුවර දුම්බර හෙණකඩ හා කළාල නිපදවීමට හණ හෙවත් නියඳ කොළවල කෙඳි ගනී."),
        q("දුම්බර කළාල රෙදි වියන විට සාම්ප්‍රදායිකව යොදා ගන්නා වර්ණ හතර කවරේද?", "රතු, කළු, කහ සහ ස්වභාවික සුදු", "නිල්, දම්, රෝස සහ රිදී", "කොළ සහ තැඹිලි පමණක්", "අළු සහ දුඹුරු පමණක්", "මහනුවර බිතුසිතුවම් මෙන්ම ස්වභාවික ශාක ඩයිවලින් ලබාගත් රතු, කළු, කහ හා සුදු වර්ණ යෙදේ."),
        q("දුම්බර කළාලවල බහුලව වියන ජ්‍යාමිතික හා සත්ව රටා මොනවාද?", "මොනරා, කුරුල්ලා, කතිර මල හා තෝඩු රටා", "මෝටර් රථ හා ගුවන් යානා", "පුනරුද ප්‍රතිමා", "වියුක්ත කැන්වස් චිත්‍ර", "අළුත් හා සාම්ප්‍රදායික දුම්බර මෝස්තර අතර කුරුල්ලා, ලණුගැටය, තාරුකා හා කතිර මල් ප්‍රධාන වේ."),
        q("මහනුවර යුගයේ දීප්තිමත් වර්ණවත් රෙදිවලින් 'නොයෙක් හැඩ කපා මසා' නිපදවන කොඩි හා තිර කලාව හඳුන්වන්නේ කුමන නමින්ද?", "අප්ලික් හෙවත් රෙදි ඔබ්බවා මැසීම", "බතික් ඉටි කලාව", "ටයි-ඩයි ගැට ගැසීම", "සිල්ක් ස්ක්‍රීන් මුද්‍රණය", "රතු හා කහ රෙදි කොටස් කපා පසුබිම් රෙද්ද මත තබා මසා දේවාල කොඩි හා වියන් සරසයි."),
        q("දළදා මාලිගාවේ 'පත්තිරිප්පුව' නිර්මාණය කළ ප්‍රසිද්ධ උඩරට වාස්තු ශිල්පියා කවුද?", "දේවේන්ද්‍ර මූලාචාරියා", "දෙල්මඩ මූලාචාරියා", "සෙනරත් පරණවිතාන", "විශ්වකර්ම", "ශ්‍රී වික්‍රම රාජසිංහ රජු සඳහා අෂ්ටාස්‍රාකාර පත්තිරිප්පුව නිර්මාණය කළේ දේවේන්ද්‍ර මූලාචාරීන්ය."),
        q("පත්තිරිප්පුවේ වාස්තු විද්‍යාත්මක සැලැස්මේ ඇති සුවිශේෂී හැඩය කුමක්ද?", "අෂ්ටාස්‍රාකාර (පැති අටක) සැලැස්ම", "වෘත්තාකාර ගෝල හැඩය", "පිරමීඩ ත්‍රිකෝණ හැඩය", "තනි සෘජුකෝණාස්‍ර හැඩය", "මහනුවර වැවට මුහුණලා පිහිටි පත්තිරිප්පුව අලංකාර අෂ්ටාස්‍රාකාර දෙමහල් ගොඩනැගිල්ලකි."),
        q("මහනුවර යුගයේ විහාර පිළිමගෙවල් තුළ දක්නට ලැබෙන 'හිටි, හිඳි හා සැතපෙන' බුදු පිළිම සාදා ඇති ප්‍රධාන මාධ්‍යය කුමක්ද?", "ගඩොල්, කෝටු හා හුණු බදාමය", "තනි පළිඟු ගලෙන් නෙළීම", "ඇලුමිනියම් වාත්තු කිරීම", "මැටි පුළුස්සා ටෙරාකොටා කිරීම", "මහනුවර යුගයේ බොහෝ බුදු පිළිම මැටි බදාමෙන් අඹා රතු හා කහ සායම් ආලේප කර ඇත."),
        q("මහනුවර යුගයේ සාදන ලද බුදු පිළිමවල 'සිවුරේ රැලි' නිරූපණය කර ඇති සුවිශේෂී ආකාරය කුමක්ද?", "සමාන්තර රැළි සිවුරු මාලාව", "රැලි රහිතව ඇඟට ඇලුණු සිවුර", "දිය බිඳු හැඩැති සිවුර", "ලොම් රෙදි මෙන් ඝන සිවුර", "සිරුර මත ඉහළ සිට පහළට රිද්මයානුකූලව පිහිටි රැළි රටා මහනුවර බුදු පිළිමවල ලක්ෂණයකි."),
        q("මහනුවර යුගයේ බුදු පිළිමවල හිස මුදුනේ දක්නට ලැබෙන 'ගිනිසිළු ආකාර සංකේතය' කුමක්ද?", "සිරස්පත", "ඌර්ණ රෝමය", "දම්සක", "චාමරය", "බුදුන් වහන්සේගේ ප්‍රඥා ආලෝකය සංකේතවත් කරන ගිනිදැල් පහක් වැනි සිරස්පත මෙහි බහුලය."),
        q("මහනුවර යුගයේ දකුණු ලංකාවේ 'වැලිගම හා තෙල්වත්ත' වැනි විහාරවල දක්නට ලැබෙන ප්‍රතිමා ශෛලියේ විශේෂත්වය කුමක්ද?", "යුරෝපීය හුරුව හා සජීවී පැහැය", "සීගිරි ශෛලියට සමාන වීම", "කළුගලින් පමණක් නෙළීම", "රන් තහඩු පමණක් එතීම", "පහතරට කලාව තුළ සාම්ප්‍රදායික උඩරට ලක්ෂණ ක්‍රමයෙන් මිනිස් රූපවල සජීවී බවකට හැරිණි."),
        q("සිංහල සාම්ප්‍රදායික මෝස්තර ශිල්පයේදී 'පුන්කලස' (පූර්ණ ඝටය) මගින් සංකේතවත් කරන්නේ කුමක්ද?", "සෞභාග්‍යය, සශ්‍රීකත්වය හා සුබ නිමිත්ත", "යුද්ධය හා විනාශය", "ශෝකය හා වියෝව", "කාලගුණ විපර්යාසය", "පොල් මල් හා පිරි ජලය පිරුණු කළය විහාර දොරටු හා ආරම්භක කැටයම්වල මංගල සංකේතයකි."),
        q("මහනුවර යුගයේ 'වැලිගම අග්‍රබෝධි' හෝ 'මුල්කිරිගල' විහාර සිතුවම්වල දැකිය හැකි පහතරට සමාජ ලක්ෂණයක් කුමක්ද?", "විදේශීය සොල්දාදුවන් හා ඔරලෝසු", "අභ්‍යවකාශ යානා ඇඳ තිබීම", "ප්‍රාග් ඓතිහාසික මැමත් සතුන්", "වියුක්ත රේඛා පමණක් වීම", "දකුණු මුහුදුබඩ පෙදෙස්වල විදේශ පාලනයේ බලපෑම සිත්තරුන් ජාතක කතා පසුබිමට එක් කළහ."),
        q("කැන්ඩියන් හෙවත් උඩරට සාම්ප්‍රදායික චිත්‍ර කලාවේ 'හිරියල්' යන ඛනිජය භාවිත කළේ කුමන වර්ණය සෑදීමටද?", "දීප්තිමත් කහ වර්ණය (Orpiment)", "තද රතු වර්ණය", "නිල් වර්ණය", "කළු වර්ණය", "ගොකටු කිරි මෙන්ම ඛනිජමය හිරියල්ද කහ වර්ණය සඳහා සිත්තරුන් යොදා ගත්හ."),
        q("මහනුවර යුගයේ සිතුවම්වල 'සාදිලිංගම්' ඛනිජය කුඩු කර දිවුල් ලාටු සමඟ මිශ්‍ර කර ලබා ගත් වර්ණය කුමක්ද?", "දීප්තිමත් රතු (සාදිලිංගම්)", "තද නිල් පැහැය", "පිරිසිදු සුදු පැහැය", "ලා කොළ පැහැය", "රසදිය සල්ෆයිඩ් ඛනිජයක් වන සාදිලිංගම් උඩරට සිතුවම්වල පසුබිම් රතු පැහැයට යොදා ගැනිණි."),
        q("මහනුවර යුගයේ චිත්‍ර සඳහා වර්ණ ද්‍රව්‍ය හා කුඩු බිත්තියට ඇලවීමට (Binder) බහුලව යොදා ගත් ශාක ලාටුව කුමක්ද?", "දිවුල් ලාටු හෝ කජු ලාටු", "පොලිතින් මැලියම්", "පාන් පිටි පාප්ප", "සබන් වතුර", "දිවුල් ගසේ ලාටු වතුරේ පොඟවා අඹරන ලද වර්ණ කුඩු සමඟ මිශ්‍ර කර ශක්තිමත් බන්ධකයක් සාදා ගනී."),
        q("මහනුවර යුගයේ දී කලාවට සම්බන්ධව වැදගත් වන 'නෙත්‍ර මංගල්‍යය' (නේත්‍ර පූජාව) යනු කුමක්ද?", "කණ්ණාඩියෙන් බලා ඇස් ඇඳීම", "විහාරයේ වහලය උළු සෙවිලි කිරීම", "ලී කැටයම් මැදීමේ දිනය", "පිත්තල පහන් සේදීමේ උත්සවය", "පිළිමයක් කෙළින්ම දෙස නොබලා කැඩපතින් බලා සිත්තරා විසින් සුබ නැකතින් නෙත් තැබීම සිදු කරයි."),
        q("මහනුවර යුගයේ 'වියන් සිතුවම්' ලෙස හඳුන්වන ලෙන් වහලයේ සිතුවම් අතරින් විශාලතම සිතුවම් පද්ධතිය ඇත්තේ කොහේද?", "දඹුල්ල රජමහා විහාරයේ", "සීගිරි කැටපත් පවුරේ", "තිවංක පිළිමගෙයි", "ඉසුරුමුණි විහාරයේ", "දඹුල්ලේ ලෙන් පහේම සිවිලිම් වක්‍ර පෘෂ්ඨ පුරා මහනුවර යුගයේ සිතුවම් නිර්මාණය වී ඇත."),
        q("මහනුවර යුගයේ පිහිටි 'මහනුවර වැව' (කිරිමුහුද) හා 'වලාකුළු බැම්ම' සැලසුම් කළේ කුමන කලා ශිල්පියාද?", "දේවේන්ද්‍ර මූලාචාරියා", "දේවරගම්පල හිමි", "රොබට් නොක්ස්", "ජෝර්ජ් කීට්", "ශ්‍රී වික්‍රම රාජසිංහ රජ සමයේ දේවේන්ද්‍ර මූලාචාරී විසින් මහනුවර වැව හා අලංකාර වලාකුළු බැම්ම තැනීය."),
        q("මහනුවර වැව වටා ඇති කෙටි තාප්පය 'වලාකුළු බැම්ම' ලෙස හඳුන්වන්නේ ඇයි?", "පහන් කුහර වලාකුළු හැඩැති නිසා", "සුදු වර්ණ පමණක් ගා ඇති නිසා", "අහසේ වලාකුළු මත පිහිටි නිසා", "ජලය ඉහළට විදින නිසා", "කඳු හා වලාකුළු රැලි මෙන් පෙනෙන අලංකාර කවාකාර හා ත්‍රිකෝණ කුහර මෙහි විශේෂත්වයයි."),
        q("මහනුවර යුගයේ 'සීන මල' (සින මල) නමැති සාම්ප්‍රදායික මෝස්තරය සාමාන්‍යයෙන් කුමන හැඩයකින් යුක්තද?", "පෙති හතරේ හෝ අටේ සැරසිලි මල", "දිගැති කිනිස්සක් ලෙස", "හතරැස් කොටුවක් ලෙස", "වක්‍ර සර්පයෙකු ලෙස", "මහනුවර බිතුසිතුවම්වල පසුබිම් හිස්තැන් පිරවීමට සහ පදක්කම්වලට සීන මල බහුලව යොදයි."),
        q("පාරම්පරික දේශීය සැරසිලි කලාවේ 'මහා ලියවැලකට' මූලික පදනම සපයන ස්වභාවික ශාක කොටස කුමක්ද?", "දළු, කොළ, කෙමිය හා පොහොට්ටු සහිත වැලක්", "වියළි ගල් කැබැල්ලක්", "මුහුදු බෙලි කටුවක්", "ගිනිකන්දක හැඩය", "වැල් මෝස්තරයේ නොකැඩී යන මූලික දණ්ඩ වටා පත්‍ර හා මල් පොහොට්ටු ශෛලිගතව යෙදේ."),
        q("මහනුවර යුගයේ 'රංගිරි දඹුලු' හා 'දෙගල්දොරුව' වැනි විහාර බිතුසිතුවම් පිළිබඳව අපට ඉතිරි වී ඇති ඓතිහාසික මූලාශ්‍රවල කියවෙන මූලික සත්‍යය කුමක්ද?", "බෞද්ධ පුනර්ජීවනයත් සමඟ ජන කලාව හා විහාර කලාව ඒකාබද්ධ වූ බව", "රාජ්‍ය පාලකයන් කලාව තහනම් කළ බව", "සියලු සිතුවම් මුහුදෙන් ගෙන ආ බව", "සිතුවම් සියල්ල කාන්තාරවල ඇඳි බව", "වැලිවිට සරණංකර හිමිගේ සංඝ ප්‍රතිසංස්කරණයත් සමඟ මහනුවර විහාර සිතුවම් පුනරුදය ඇති විය."),
        q("සාම්ප්‍රදායික කලා නිර්මාණ අතර 'ඇම්බැක්කේ දේවාලයේ' දැව කුළුණු මත කැටයම් කර නැති මෝස්තරය කුමක්ද?", "මෝටර් රථ හා ගුවන් යානා", "පංචනාරි ඝටය", "නැටුම්කරුවන් හා මල්ලවපොර", "හංස පූට්ටුව හා සැරපෙන්දියා", "ඇම්බැක්කේ කැටයම්වල සාම්ප්‍රදායික සත්ව, ක්‍රීඩා, නැටුම් හා මල් මෝස්තර පමණක් දක්නට ලැබේ."),
        q("ඇම්බැක්කේ දේවාලයේ දැව කුළුණු පාදමේ ඇති චතුරස්‍රාකාර කොටසේ සිට අෂ්ටාස්‍රාකාර කොටසට මාරු වන ස්ථානයේ ඇති කැටයම් කුමක්ද?", "නාග බන්ධන හෙවත් අර්ධ පද්ම සැරසිලි", "සිමෙන්ති ප්ලාස්ටර්", "වීදුරු කැට", "ලෝහ ඇණ පේළිය", "සිව්රැස් කඳ අට්ටාස්‍රයකට හරවන ස්ථානයේ නාගබන්ධ හා ලියපත කැටයම් අලංකාරව යොදා ඇත."),
        q("මහනුවර යුගයේ දැකිය හැකි 'පිළිමගෙයක සතර දිසාවේ' සිතුවම්වලින් පිටත මණ්ඩපයේ බහුලව අඳින රූප මොනවාද?", "සතරවරම් දෙවිවරුන් හා දොරටුපාල රූප", "ග්‍රීක දෙවිවරුන්", "නවීන ක්‍රීඩකයන්", "ප්‍රාග් ඓතිහාසික දඩයක්කරුවන්", "විහාරය ආරක්ෂා කරන සංකේත ලෙස දොරටුපාලයන් හා දේව රූප ඇතුළුවන තැන අඳිනු ලැබේ."),
        q("දේශීය කලා කර්මාන්ත අතර 'ගාලු කොටුවේ හා මාතර' ආශ්‍රිතව වර්ධනය වූ බීරළු රේන්ද හා කැස්බෑ ලෙලි කැටයම් අයත් වන්නේ කුමන කාල පරිච්ඡේදයටද?", "පහතරට යටත්විජිත ආභාසිත පසු මහනුවර යුගයට", "ප්‍රාග් ඓතිහාසික ගල් යුගයට", "අනුරාධපුර මුල් යුගයට", "පොළොන්නරු යුගයට", "ලන්දේසි හා පෘතුගීසි ආභාසය සමඟ දකුණු වෙරළබඩ ප්‍රදේශවල මෙම සියුම් අත්කම් කලා ප්‍රචලිත විය."),
        q("මහනුවර යුගයේ 'විහාර කොඩි' හා 'සේසත්' පෙරහැරවලදී රැගෙන යාමෙන් පිළිබිඹු වන සංස්කෘතික අර්ථය කුමක්ද?", "රාජ්‍ය හා ආගමික ගෞරවය, දිසා අනන්‍යතාව හා කලාත්මක සැරසිල්ල", "වෙළඳ දැන්වීම් ප්‍රචාරය කිරීම", "ක්‍රීඩා තරගාවලි ලකුණු ගණනය", "නාවික කාලගුණ අනතුරු ඇඟවීම", "හිරු සඳු, සිංහ, හංස හා භේරුණ්ඩ කොඩි හා සේසත් ශ්‍රී ලාංකේය උත්සව කලාවේ අනන්‍යතාවයි."),
        q("මහනුවර යුගයේ සිතුවම්වල 'සමුද්‍රය හා ගංගා' (ජලය) ඇඳීම සඳහා සිත්තරා යොදා ගත් සාම්ප්‍රදායික ක්‍රමය කුමක්ද?", "මාළුවන් සහිත සමාන්තර රැලි රේඛා රටාවක් ලෙස ඇඳීම", "ඡායාරූප පරිදි ජල පරාවර්තන ඇඳීම", "තනි කළු තීන්ත කොටුවක් ගෑම", "ජලය වෙනුවට අකුරු ලිවීම", "පැරණි සාම්ප්‍රදායික රීතියට අනුව රිද්මයානුකූල වක්‍ර රේඛා සහ මත්ස්‍ය රූපවලින් ජලය දක්වයි."),
        q("මහනුවර සම්ප්‍රදායේ 'වෘක්ෂ හා ජල රටා' පවා සැරසිලිමය ස්වභාවයක් ගැනීමට හේතුව කුමක්ද?", "සැරසිලිමය රිද්මයට මුල් තැන දීම", "ශිල්පීන් ජලය දැක නොතිබීම", "වර්ණ භාවිතය තහනම් වීම", "කාලය ඉතිරි කිරීමට කුරුටු ගෑම", "සමස්ත දේශීය චිත්‍ර කලාවම පැතලි සැරසිලිමය (Decorative) න්‍යායක් මත ගොඩනැගී ඇත."),
        q("උඩරට සාම්ප්‍රදායික කැටයම් හා සිතුවම් අතර 'පලාපෙති' මෝස්තරය බොහෝ විට යොදන්නේ කුමන කාර්යය සඳහාද?", "චිත්‍ර තීරු දාර හා කුළුණු සැරසීම", "පසුබිම් අහස පිරවීමට", "රජුගේ මුහුණ ඇඳීමට", "සිතුවමේ මැද ශීර්ෂපාඨ ලිවීමට", "කතා තීරු දෙකක් වෙන් කරන සීමා තීරු අලංකාර කිරීමට පලාපෙති බෝඩරය බහුලව යෙදේ."),
        q("සිංහල සාම්ප්‍රදායික මෝස්තර කලාවේදී 'නෙළුම් මල' පූජනීය හා කලාත්මක සංකේතයක් ලෙස යොදා ගන්නේ ඇයි?", "පවිත්‍රතාවය, අධ්‍යාත්මික ප්‍රබෝධය හා පිරිසිදු බව නිරූපණය කරන බැවින්", "එය ආහාරයක් පමණක් වන බැවින්", "එය ඇඳීමට පහසුම හතරැස් හැඩය නිසා", "කාන්තාර පරිසරය සංකේතවත් කිරීමට", "මඩේ පිපුණත් අපවිත්‍ර නොවන නෙළුම සඳකඩපහණේ සිට මහනුවර වියන් සිතුවම් දක්වා ප්‍රධාන සංකේතයකි."),
        q("මහනුවර යුගයේ චිත්‍ර ශිල්පයේ සඳහන් 'වලිත්ති ගෑම' යනු කුමක්ද?", "සිතුවම් ඇඳ අවසන් වූ පසු දොරණ තෙල් හා දුම්මල මිශ්‍ර ආරක්ෂිත වාර්නිෂ් තවරාලීම", "බිත්තියට මුලින්ම රතු මැටි ගෑම", "පින්සල් සෝදා පිරිසිදු කිරීම", "පැරණි සිතුවම් සූරා ඉවත් කිරීම", "සිතුවමේ වර්ණ නොමැකී දිගු කල් පැවතීම සඳහා වලිත්ති ආලේප කිරීම මහනුවර තාක්ෂණයේ පියවරකි."),
        q("කැන්ඩියන් සම්ප්‍රදායේ 'විහාර බිතුසිතුවම්වල' සමූහ චරිත ඇඳීමේදී ඒවායේ පිහිටීම දක්වා ඇත්තේ කෙසේද?", "එකම තිරස් රේඛාවක් මත පෙළට සිටුවා හෝ මදක් එකිනෙක පසුපසින් පෙනෙන සේ", "ගැඹුරු කේන්ද්‍රීය දෘෂ්ටිකෝණයකින් කුඩා කරමින්", "අහසේ පාවෙන ආකාරයට හිස යටිකුරු කර", "කොටු දැලක් තුළ තනි තනිව වෙන් කර", "ද්විමාන ශෛලිය නිසා සියලු රූප පහළ දාරය මත පෙළගස්වා කතාව ගලා යාම පෙන්වයි."),
        q("මහනුවර යුගයේ 'ලේනා වැල්' හා 'පිච්ච මල්' වැනි රටා දැව කැටයමට වඩා බහුලව දැකිය හැක්කේ කුමන මාධ්‍යයකද?", "රිදී හා පිත්තල කැටයම් හා වියන් රෙදි සිතුවම්වල", "කළුගල් දාගැබ් කොත්වල", "මැටි පුළුස්සන ගඩොල්වල", "ප්‍රාග් ඓතිහාසික සෙල්ලිපිවල", "සියුම් මල් පොහොට්ටු හා වැල් රටා ලෝහ කර්මාන්ත, ඇත්දත් හා වියන් සැරසිලිවල බහුලව යෙදේ."),
        q("මහනුවර යුගයේ කලාකරුවාගේ අධ්‍යාත්මික හා සමාජීය පසුබිම පිළිබඳව නිවැරදි ප්‍රකාශය කුමක්ද?", "රාජකීය ගම්වර ලැබූ කුල පරම්පරාගත ශිල්පීන් හා උගත් භික්ෂූන් අතින් කලාව පෝෂණය විය", "ඔවුහු නූතන කලා පාසල්වල උපාධි ලබා සිටියහ", "චිත්‍ර ඇඳීම විදේශීය වෙළඳ සමාගම්වල රැකියාවක් විය", "ඔවුන් සිය නම් රන් අකුරින් සෑම රූපයකම ලියූහ", "පාරම්පරික ගුරුකුල රටාව යටතේ ශිල්පීන් ආගමික භක්තියෙන් යුතුව විහාර කර්මාන්ත සිදු කළහ."),
        q("උඩරට සාම්ප්‍රදායික 'සඳකඩපහණ' අනුරාධපුර හා පොළොන්නරු සඳකඩපහණට වඩා වෙනස් වන ප්‍රධාන ලක්ෂණය කුමක්ද?", "ත්‍රිකෝණ හැඩය හා සරල ලියවැල", "මිසර ස්පින්ක්ස් රූප ඇතුළත් වීම", "වීදුරු මොසැයික්වලින් නිමවීම", "පියගැට පහළොවක් උස වීම", "මහනුවර යුගය වන විට ගඩලාදෙණිය, ඇම්බැක්කේ වැනි තැන්වල සඳකඩපහණ සරල ජ්‍යාමිතික හැඩයක් ගනී.")
    )
}
